 IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.tokens.total') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.cores') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.exempt') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.explored') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.tokens_settled') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.meter.ok') IN ('true', 'false'), 0) AND json_type(rest, '$.event') IS NULL));
CREATE TABLE spawn_lists(n INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('tag', 'item', 'fault', 'scratch_loose', 'ci_direct', 'app', 'app_before', 'app_failed', 'app_missing', 'app_relaunched')), ord INTEGER NOT NULL, value TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (n, kind, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX spawn_lists_value ON spawn_lists(kind, value);
CREATE INDEX spawn_lists_at ON spawn_lists(at);
CREATE TABLE spawn_app_exits(n INTEGER NOT NULL, app TEXT NOT NULL, gone_by TEXT, last_seen TEXT, at REAL NOT NULL, PRIMARY KEY (n, app)) STRICT, WITHOUT ROWID;
CREATE INDEX spawn_app_exits_at ON spawn_app_exits(at);
CREATE INDEX agent_spawns_tool ON agent_spawns(tool_use_id);
