  INSERT INTO spawn_lists SELECT NEW.n, 'ci_direct', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.ci_direct') e WHERE (json_type(NEW.body, '$.ci_direct') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.ci_direct') e WHERE e.type <> 'text'));
  INSERT INTO spawn_lists SELECT NEW.n, 'app', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.apps') e WHERE (json_type(NEW.body, '$.apps') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps') e WHERE e.type <> 'text'));
  INSERT INTO spawn_lists SELECT NEW.n, 'app_before', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.apps.before') e WHERE (json_type(NEW.body, '$.apps.before') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps.before') e WHERE e.type <> 'text'));
  INSERT INTO spawn_lists SELECT NEW.n, 'app_failed', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.apps.failed') e WHERE (json_type(NEW.body, '$.apps.failed') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps.failed') e WHERE e.type <> 'text'));
  INSERT INTO spawn_lists SELECT NEW.n, 'app_missing', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.apps.missing') e WHERE (json_type(NEW.body, '$.apps.missing') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps.missing') e WHERE e.type <> 'text'));
  INSERT INTO spawn_lists SELECT NEW.n, 'app_relaunched', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.apps.relaunched') e WHERE (json_type(NEW.body, '$.apps.relaunched') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps.relaunched') e WHERE e.type <> 'text'));
  INSERT INTO spawn_app_exits SELECT NEW.n, e.key, e.value ->> '$.gone_by', e.value ->> '$.last_seen', NEW.at FROM json_each(NEW.body, '$.apps.exits') e WHERE (json_type(NEW.body, '$.apps.exits') = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.apps.exits') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'gone_by' AND k.type IN ('text')) OR (k.key = 'last_seen' AND k.type IN ('text'))))));
END;
CREATE TRIGGER agent_spawns_refill AFTER UPDATE OF body ON agent_spawns WHEN NEW.rest IS NULL AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM agent_spawns WHERE n = NEW.n;
  INSERT INTO agent_spawns(n, at, event, agent, item, body) VALUES (NEW.n, NEW.at, NEW.event, NEW.agent, NEW.item, NEW.body);
END;
CREATE TRIGGER agent_spawns_bad AFTER UPDATE OF body ON agent_spawns WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE agent_spawns SET rest = NULL WHERE n = NEW.n;
END;
CREATE TRIGGER agent_spawns_gone AFTER DELETE ON agent_spawns BEGIN
  DELETE FROM spawn_app_exits WHERE n = OLD.n;
  DELETE FROM spawn_lists WHERE n = OLD.n;
END;
